{"code":"const dir = "/tmp/pcmp"; await Bun.$`rm -rf ${dir} && mkdir -p ${dir}`;
await Bun.$`cp src/parser_a.rs src/parser_b.rs ${dir}/`;
await Bun.write(dir + "/main.rs", `
mod parser_a; mod parser_b;
use parser_a::*; use parser_b::*;
fn ev_a(e:&Expr)->i64{match e{Expr::Number(n)=>*n,Expr::Binary(l,o,r)=>{let(a,b)=(ev_a(l),ev_a(r));if *o=='+'{a+b}else{a-b}}}}
fn ev_b(e:&AstNode)->i64{match e{AstNode::Val(n)=>*n,AstNode::Op(o,l,r)=>{let(a,b)=(ev_b(l),ev_b(r));if *o=='+'{a+b}else{a-b}}}}
fn main(){
 for s in ["1+2","1 +2","1 + 2","10-2-3","1 2","1+","+1","","99999999999999999999","1+2x"]{
  let a=RecursiveDescentParser::new(s).parse();
  let toks:Vec<String>=s.split_whitespace().map(String::from).collect();
  println!("A {:?} -> {:?} {}",s,a,a.as_ref().map(|e|ev_a(e).to_string()).unwrap_or_default());
 }
 for t in [vec!["1","+","2"],vec!["10","-","2","-","3"],vec!["1","2","+"],vec!["1","+"],vec![],vec!["1","*","2"],vec!["+","1","2"],vec!["1","+","2","-","3"],vec!["1","2","3"]]{
  let t:Vec<String>=t.into_iter().map(String::from).collect();
  let b=ShiftReduceParser::parse(&t);
  println!("B {:?} -> {:?} {}",t,b,b.as_ref().map(|e|ev_b(e).to_string()).unwrap_or_default());
 }
}`);
const r = await Bun.$`cd ${dir} && rustc --edition 2021 -A warnings main.rs -o m 2>&1 && ./m; rustc --version`.nothrow().text(); print(r)","language":"js","summary":"Run both parsers on probe inputs in /tmp"}
